package com.phamquocviet.registrationservice.config;
import com.phamquocviet.registrationservice.security.JwtAuthFilter;import jakarta.servlet.http.HttpServletResponse;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/registrations/**").hasAnyRole("ADMIN","STUDENT").anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((r,p,x)->json(p,401,"Unauthorized","Yêu cầu JWT hợp lệ")).accessDeniedHandler((r,p,x)->json(p,403,"Forbidden","Bạn không có quyền thực hiện thao tác này"))).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}private static void json(HttpServletResponse p,int s,String e,String m)throws java.io.IOException{p.setStatus(s);p.setContentType("application/json");p.getWriter().write("{\"status\":"+s+",\"error\":\""+e+"\",\"message\":\""+m+"\"}");}}
